"use client";

import { useEffect, useMemo, useRef, useState, type FormEvent, type PointerEvent as ReactPointerEvent, type ReactNode } from "react";
import { BulkTaskToolbar, type BulkAction } from "@/components/bulk-task-toolbar";
import { ManagerActionCenter } from "@/components/manager-action-center";
import type { ManagerActionRisk } from "@/lib/reporting";

type Member = { role: string; teamGroupId: string | null; teamGroup: { id: string; name: string } | null; user: { id: string; name: string | null; email: string } };
type Label = { id: string; name: string; color: string };
type TaskCountKey = "updatedProductsCount" | "newProductsCount" | "updatedImagesCount" | "newImagesCount";
type Task = { id: string; title: string; description: string | null; status: string; priority: string; dueAt: string | Date | null; startedAt: string | Date | null; completedAt: string | Date | null; createdAt?: string | Date; updatedAt?: string | Date; estimatedMinutes: number | null; remainingMinutes: number | null; actualMinutes: number | null; blockedAt: string | Date | null; blockedReason: string | null; blockerTaskId: string | null; recurrence: string; recurrenceInterval: number; updatedProductsCount: number | null; newProductsCount: number | null; updatedImagesCount: number | null; newImagesCount: number | null; createdByUserId: string; assigneeUserId: string | null; followUpWith: string | null; assignee: { id: string; name: string | null; email: string } | null; labels: Label[] };
type ChecklistItem = { id: string; title: string; completed: boolean; position: number };
type TaskDetail = Task & { blockerTask?: { id: string; title: string; status: string } | null; sourceEmails?: { id: string; subject: string; senderAddress: string; receivedAt: string; connector: { mailboxAddress: string } }[]; createdBy: { id: string; name: string | null; email: string }; checklistItems: ChecklistItem[]; comments: { id: string; body: string; createdAt: string; author: { id: string; name: string | null; email: string } }[]; activities: { id: string; type: string; createdAt: string; actor: { name: string | null; email: string } }[] };
type FilterState = { query: string; statuses: string[]; priorities: string[]; assignees: string[]; creator: string; due: string; dueFrom: string; dueTo: string; completed: string; recurrence: string; followUpWith: string; teamGroupId: string; labels: string[]; attention: boolean; mineOnly: boolean };
type SavedView = { id: string; userId: string; name: string; shared: boolean; filters: unknown };
type ViewMode = "board" | "list" | "calendar";

const taskStatuses = [["TODO", "To do"], ["IN_PROGRESS", "In progress"], ["DONE", "Completed"], ["NO_ACTION_NEEDED", "No Action Needed"]] as const;
const boardColumns = taskStatuses.slice(0, 3);
const priority: Record<string, string> = { LOW: "Low", MEDIUM: "Medium", HIGH: "High", URGENT: "Urgent" };
const taskCountOptions: ReadonlyArray<{ key: TaskCountKey; label: string }> = [
  { key: "updatedProductsCount", label: "Updated Products Count" },
  { key: "newProductsCount", label: "New Products Count" },
  { key: "updatedImagesCount", label: "Updated Images Count" },
  { key: "newImagesCount", label: "New Images Count" },
];
const emptyFilters: FilterState = { query: "", statuses: [], priorities: [], assignees: [], creator: "all", due: "all", dueFrom: "", dueTo: "", completed: "all", recurrence: "all", followUpWith: "", teamGroupId: "", labels: [], attention: false, mineOnly: false };
type ActionCenterData = { total: number; counts: Record<ManagerActionRisk, number>; taskIds: Record<Exclude<ManagerActionRisk, "overloaded">, string[]>; overloadedMemberIds: string[] };

function dateKey(value: string | Date) { const date = new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function startOfDay(value = new Date()) { const date = new Date(value); date.setHours(0, 0, 0, 0); return date; }
function addDays(value: Date, days: number) { const date = new Date(value); date.setDate(date.getDate() + days); return date; }
function startOfWeek(value: Date) { const date = startOfDay(value); date.setDate(date.getDate() - date.getDay()); return date; }
function inRange(value: string | Date, from: Date, to: Date) { const time = new Date(value).getTime(); return time >= from.getTime() && time < to.getTime(); }
function buildCalendarDays(month: Date) { const first = new Date(month.getFullYear(), month.getMonth(), 1); const start = addDays(first, -first.getDay()); return Array.from({ length: 42 }, (_, index) => addDays(start, index)); }
function normalizeFilters(value: unknown): FilterState { if (!value || typeof value !== "object") return { ...emptyFilters }; const raw = value as Partial<FilterState>; return { ...emptyFilters, ...raw, statuses: raw.statuses ?? [], priorities: raw.priorities ?? [], assignees: raw.assignees ?? [], labels: raw.labels ?? [] }; }
function toggleValue(items: string[], value: string) { return items.includes(value) ? items.filter((item) => item !== value) : [...items, value]; }
function personName(member: Member) { return member.user.name || member.user.email; }
function dueLabel(value: string | Date | null, done = false) { if (!value) return null; const date = new Date(value); const overdue = !done && date.getTime() < Date.now(); return <span className={overdue ? "due-date overdue" : "due-date"}>{overdue ? "Overdue" : "Due"} {date.toLocaleDateString()}</span>; }
function needsAttention(task: Task, now = new Date()) { if (task.status === "NO_ACTION_NEEDED") return false; const overdue = !!task.dueAt && task.status !== "DONE" && new Date(task.dueAt) < now; const soon = !!task.dueAt && task.status !== "DONE" && inRange(task.dueAt, now, addDays(now, 2)); const stalled = task.status === "IN_PROGRESS" && !task.dueAt; return overdue || soon || task.priority === "URGENT" || !task.assigneeUserId || stalled || Boolean(task.blockedAt || task.blockerTaskId) || !task.estimatedMinutes; }

function MultiFilter({ id, label, count, open, onToggle, children }: { id: string; label: string; count: number; open: boolean; onToggle: () => void; children: ReactNode }) {
  return <div className={`filter-menu ${open ? "open" : ""}`}><button type="button" className="filter-trigger" aria-expanded={open} aria-controls={`${id}-menu`} onClick={onToggle}><span>{label}</span>{count > 0 && <strong>{count}</strong>}<span className="chevron" aria-hidden="true">⌄</span></button>{open && <div className="filter-popover" id={`${id}-menu`} role="group" aria-label={`${label} options`}><div className="filter-popover-heading"><strong>{label}</strong><span>{count ? `${count} selected` : "Select one or more"}</span></div>{children}</div>}</div>;
}

export function BoardClient({ initialTasks, members, role, canManageWorkspace: canManageWorkspaceProp, managerActionCenter, workspaceId, currentUserId, initialLabels, initialSavedViews }: { initialTasks: Task[]; members: Member[]; role: string; canManageWorkspace: boolean; managerActionCenter: ActionCenterData; workspaceId: string; currentUserId: string; initialLabels: Label[]; initialSavedViews: SavedView[] }) {
  const [tasks, setTasks] = useState(initialTasks);
  const [labels, setLabels] = useState(initialLabels);
  const [savedViews, setSavedViews] = useState(initialSavedViews);
  const [filters, setFilters] = useState<FilterState>({ ...emptyFilters });
  const [selectedViewId, setSelectedViewId] = useState("");
  const [viewName, setViewName] = useState("");
  const [shareView, setShareView] = useState(false);
  const [openFilter, setOpenFilter] = useState<string | null>(null);
  const [showMoreFilters, setShowMoreFilters] = useState(false);
  const [showMobileFilters, setShowMobileFilters] = useState(false);
  const [showInsights, setShowInsights] = useState(false);
  const [showSaveView, setShowSaveView] = useState(false);
  const [showLabelManager, setShowLabelManager] = useState(false);
  const [creating, setCreating] = useState(false);
  const [error, setError] = useState("");
  const [selected, setSelected] = useState<TaskDetail | null>(null);
  const [selectedTaskIds, setSelectedTaskIds] = useState<Set<string>>(new Set());
  const [riskFilter, setRiskFilter] = useState<ManagerActionRisk | null>(null);
  const [comment, setComment] = useState("");
  const [checklistTitle, setChecklistTitle] = useState("");
  const [saving, setSaving] = useState(false);
  const [view, setView] = useState<ViewMode>("board");
  const [calendarMonth, setCalendarMonth] = useState(() => new Date());
  const [draggingTaskId, setDraggingTaskId] = useState<string | null>(null);
  const [dragOverStatus, setDragOverStatus] = useState<string | null>(null);
  const [loadingTaskId, setLoadingTaskId] = useState<string | null>(null);
  const detailCache = useRef(new Map<string, Promise<TaskDetail>>());
  const pointerDrag = useRef<{ taskId: string; startX: number; startY: number; active: boolean; status: string | null } | null>(null);
  const suppressCardClick = useRef(false);
  const controlsRef = useRef<HTMLDivElement>(null);
  const canCreate = role !== "VIEWER";
  const canManageWorkspace = canManageWorkspaceProp;
  const followUpWithOptions = useMemo(() => Array.from(new Set(tasks.map((task) => task.followUpWith?.trim()).filter((value): value is string => Boolean(value)))).sort((a, b) => a.localeCompare(b)), [tasks]);
  const teamGroupOptions = useMemo(() => Array.from(new Map(members.flatMap((member) => member.teamGroup ? [[member.teamGroup.id, member.teamGroup] as const] : [])).values()).sort((a, b) => a.name.localeCompare(b.name)), [members]);

  useEffect(() => {
    function closeFloatingControls(event: PointerEvent) { if (!controlsRef.current?.contains(event.target as Node)) { setOpenFilter(null); setShowSaveView(false); } }
    function closeOnEscape(event: KeyboardEvent) { if (event.key === "Escape") { setOpenFilter(null); setShowSaveView(false); setShowLabelManager(false); setShowMobileFilters(false); setSelected(null); } }
    document.addEventListener("pointerdown", closeFloatingControls);
    document.addEventListener("keydown", closeOnEscape);
    return () => { document.removeEventListener("pointerdown", closeFloatingControls); document.removeEventListener("keydown", closeOnEscape); };
  }, []);

  const visibleTasks = useMemo(() => {
    const now = new Date(); const today = startOfDay(now); const tomorrow = addDays(today, 1); const dayAfterTomorrow = addDays(today, 2); const weekStart = startOfWeek(now); const nextWeek = addDays(weekStart, 7); const followingWeek = addDays(weekStart, 14); const monthStart = new Date(now.getFullYear(), now.getMonth(), 1); const nextMonth = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    const memberTeamGroups = new Map(members.map((member) => [member.user.id, member.teamGroupId]));
    return tasks.filter((task) => {
      if (filters.query && !`${task.title} ${task.description || ""}`.toLowerCase().includes(filters.query.toLowerCase())) return false;
      if (filters.statuses.length && !filters.statuses.includes(task.status)) return false;
      if (filters.priorities.length && !filters.priorities.includes(task.priority)) return false;
      if (filters.assignees.length && !filters.assignees.some((id) => id === "__unassigned__" ? !task.assigneeUserId : task.assigneeUserId === id)) return false;
      if (filters.creator !== "all" && task.createdByUserId !== filters.creator) return false;
      if (filters.mineOnly && task.assigneeUserId !== currentUserId && task.createdByUserId !== currentUserId) return false;
      if (filters.labels.length && !filters.labels.every((id) => task.labels.some((label) => label.id === id))) return false;
      if (filters.recurrence === "recurring" && task.recurrence === "NONE") return false;
      if (filters.recurrence === "not-recurring" && task.recurrence !== "NONE") return false;
      if (filters.followUpWith === "__none__" && task.followUpWith) return false;
      if (filters.followUpWith && filters.followUpWith !== "__none__" && task.followUpWith !== filters.followUpWith) return false;
      if (filters.teamGroupId === "__none__" && task.assigneeUserId && memberTeamGroups.get(task.assigneeUserId)) return false;
      if (filters.teamGroupId && filters.teamGroupId !== "__none__" && (!task.assigneeUserId || memberTeamGroups.get(task.assigneeUserId) !== filters.teamGroupId)) return false;
      if (riskFilter && riskFilter !== "overloaded" && !managerActionCenter.taskIds[riskFilter].includes(task.id)) return false;
      if (riskFilter === "overloaded" && (!task.assigneeUserId || !managerActionCenter.overloadedMemberIds.includes(task.assigneeUserId))) return false;
      if (filters.completed !== "all") {
        if (!task.completedAt) return false;
        if (filters.completed === "today" && !inRange(task.completedAt, today, tomorrow)) return false;
        if (filters.completed === "this-week" && !inRange(task.completedAt, weekStart, nextWeek)) return false;
        if (filters.completed === "this-month" && !inRange(task.completedAt, monthStart, nextMonth)) return false;
      }
      if (filters.due !== "all") {
        if (filters.due === "no-date") { if (task.dueAt) return false; }
        else {
          if (!task.dueAt) return false; const due = new Date(task.dueAt);
          if (filters.due === "overdue" && (task.status === "DONE" || due >= now)) return false;
          if (filters.due === "today" && !inRange(due, today, tomorrow)) return false;
          if (filters.due === "tomorrow" && !inRange(due, tomorrow, dayAfterTomorrow)) return false;
          if (filters.due === "this-week" && !inRange(due, today, nextWeek)) return false;
          if (filters.due === "next-week" && !inRange(due, nextWeek, followingWeek)) return false;
          if (filters.due === "custom") { const from = filters.dueFrom ? startOfDay(new Date(`${filters.dueFrom}T00:00:00`)) : null; const to = filters.dueTo ? addDays(startOfDay(new Date(`${filters.dueTo}T00:00:00`)), 1) : null; if ((from && due < from) || (to && due >= to)) return false; }
        }
      }
      if (filters.attention && !needsAttention(task, now)) return false;
      return true;
    });
  }, [tasks, filters, currentUserId, members, managerActionCenter, riskFilter]);
  const grouped = useMemo(() => Object.fromEntries(boardColumns.map(([key]) => [key, visibleTasks.filter((task) => task.status === key)])), [visibleTasks]);
  const noActionNeededCount = visibleTasks.filter((task) => task.status === "NO_ACTION_NEEDED").length;
  const selectedEditable = selected ? canEditTask(selected) : false;
  const calendarDays = useMemo(() => buildCalendarDays(calendarMonth), [calendarMonth]);
  const tasksByDate = useMemo(() => visibleTasks.reduce<Record<string, Task[]>>((result, task) => { if (task.dueAt) (result[dateKey(task.dueAt)] ??= []).push(task); return result; }, {}), [visibleTasks]);
  const filterChips = [filters.statuses.length ? `Status: ${filters.statuses.length}` : "", filters.priorities.length ? `Priority: ${filters.priorities.length}` : "", filters.assignees.length ? `Assignee: ${filters.assignees.length}` : "", filters.creator !== "all" ? "Creator" : "", filters.due !== "all" ? `Due: ${filters.due.replaceAll("-", " ")}` : "", filters.completed !== "all" ? `Completed: ${filters.completed.replaceAll("-", " ")}` : "", filters.recurrence !== "all" ? "Recurrence" : "", filters.followUpWith ? `Follow up with: ${filters.followUpWith === "__none__" ? "No person" : filters.followUpWith}` : "", filters.teamGroupId ? `Team: ${filters.teamGroupId === "__none__" ? "No team group" : teamGroupOptions.find((item) => item.id === filters.teamGroupId)?.name || "Team"}` : "", filters.labels.length ? `Labels: ${filters.labels.length}` : "", filters.attention ? "Needs attention" : "", filters.mineOnly ? "My tasks" : "", riskFilter ? `Manager: ${riskFilter}` : ""].filter(Boolean);
  const moreFilterCount = Number(filters.creator !== "all") + Number(filters.due !== "all") + Number(filters.completed !== "all") + Number(filters.recurrence !== "all") + Number(Boolean(filters.followUpWith)) + Number(Boolean(filters.teamGroupId)) + filters.labels.length;

  function canEditTask(task: Task) { return role === "OWNER" || role === "ADMIN" || (role === "MEMBER" && (task.createdByUserId === currentUserId || task.assigneeUserId === currentUserId)); }
  const allVisibleSelected = visibleTasks.length > 0 && visibleTasks.every((task) => selectedTaskIds.has(task.id));
  function toggleTaskSelection(taskId: string) { setSelectedTaskIds((current) => { const next = new Set(current); if (next.has(taskId)) next.delete(taskId); else next.add(taskId); return next; }); }
  function toggleAllVisibleTasks() { setSelectedTaskIds((current) => { const next = new Set(current); if (allVisibleSelected) visibleTasks.forEach((task) => next.delete(task.id)); else visibleTasks.forEach((task) => next.add(task.id)); return next; }); }
  async function bulkUpdate(action: BulkAction, value: string | null) {
    const taskIds = [...selectedTaskIds]; if (!taskIds.length) return;
    setSaving(true); setError("");
    const response = await fetch(`/api/workspaces/${workspaceId}/tasks/bulk`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ taskIds, action, ...(action === "ASSIGN" ? { assigneeUserId: value } : action === "STATUS" ? { status: value } : action === "PRIORITY" ? { priority: value } : action === "DUE_DATE" ? { dueAt: value } : { labelId: value }) }) });
    setSaving(false);
    if (!response.ok) return setError((await response.json()).error || "Bulk update failed");
    const result = await response.json();
    const updatedIds = new Set(result.tasks.map((task: Task) => task.id));
    setTasks((current) => current.map((task) => { const updated = result.tasks.find((item: Task) => item.id === task.id); return updated ? { ...task, ...updated } : task; }));
    setSelectedTaskIds((current) => new Set([...current].filter((id) => !updatedIds.has(id))));
    result.tasks.forEach((task: Task) => detailCache.current.delete(task.id));
    if (result.recurringTasks?.length) setTasks((current) => [...result.recurringTasks.map((task: Task) => ({ ...task, assignee: members.find((member) => member.user.id === task.assigneeUserId)?.user || null, labels: [] })), ...current]);
    setError(`${result.updated} task${result.updated === 1 ? "" : "s"} updated${result.failed?.length ? `; ${result.failed.length} failed` : ""}.`);
  }
  function assignmentControls(task: Task, compact = false) {
    if (task.assignee) return <span>{task.assignee.name || task.assignee.email}</span>;
    return <div className={`assignment-controls ${compact ? "compact" : ""}`} onClick={(event) => event.stopPropagation()} onPointerDown={(event) => event.stopPropagation()} onKeyDown={(event) => event.stopPropagation()}><button type="button" onClick={() => assignUnassignedTask(task, currentUserId)}>Pick for me</button><select aria-label={`Assign ${task.title}`} defaultValue="" onChange={(event) => { void assignUnassignedTask(task, event.target.value); event.currentTarget.value = ""; }}><option value="" disabled>Assign to...</option>{members.map((member) => <option key={member.user.id} value={member.user.id}>{personName(member)}</option>)}</select></div>;
  }
  function updateFilter<K extends keyof FilterState>(key: K, value: FilterState[K]) { setFilters((current) => ({ ...current, [key]: value })); setSelectedViewId(""); }
  function toggleFilterMenu(name: string) { setOpenFilter((current) => current === name ? null : name); setShowSaveView(false); }

  async function createTask(formData: FormData) { setError(""); const response = await fetch("/api/tasks", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ workspaceId, title: formData.get("title"), priority: formData.get("priority"), assigneeUserId: formData.get("assigneeUserId") || null }) }); if (!response.ok) return setError((await response.json()).error); const task = await response.json(); task.assignee = members.find((member) => member.user.id === task.assigneeUserId)?.user || null; task.labels = []; setTasks((items) => [task, ...items]); setCreating(false); }
  async function assignUnassignedTask(task: Task, assigneeUserId: string) {
    if (!assigneeUserId || task.assigneeUserId) return;
    setError("");
    const response = await fetch(`/api/tasks/${task.id}/assign`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ assigneeUserId }) });
    if (!response.ok) return setError((await response.json()).error);
    const updated = await response.json();
    detailCache.current.delete(task.id);
    setTasks((items) => items.map((item) => item.id === task.id ? { ...item, ...updated } : item));
    setSelected((current) => current?.id === task.id ? { ...current, ...updated } : current);
    setError(`${task.title} assigned to ${updated.assignee?.name || updated.assignee?.email}.`);
  }
  async function updateStatus(task: Task, status: string) { if (task.status === status) return; const previous = task; const completedAt = status === "DONE" ? task.completedAt || new Date().toISOString() : null; setTasks((items) => items.map((item) => item.id === task.id ? { ...item, status, completedAt } : item)); const response = await fetch(`/api/tasks/${task.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ status }) }); if (!response.ok) { setTasks((items) => items.map((item) => item.id === task.id ? previous : item)); return setError((await response.json()).error); } detailCache.current.delete(task.id); const updated = await response.json(); setTasks((items) => items.map((item) => item.id === task.id ? { ...item, ...updated } : item)); if (updated.recurringTask) { const assignee = members.find((member) => member.user.id === updated.recurringTask.assigneeUserId)?.user || null; setTasks((items) => [{ ...updated.recurringTask, assignee, labels: [] }, ...items]); setError(`Next recurring task created: ${updated.recurringTask.title}`); } }
  function startPointerDrag(event: ReactPointerEvent<HTMLElement>, task: Task) {
    if (event.button !== 0 || !canEditTask(task) || (event.target as HTMLElement).closest("button, select, input, textarea, a")) return;
    pointerDrag.current = { taskId: task.id, startX: event.clientX, startY: event.clientY, active: false, status: null };
    event.currentTarget.setPointerCapture(event.pointerId);
  }
  function movePointerDrag(event: ReactPointerEvent<HTMLElement>) {
    const drag = pointerDrag.current; if (!drag) return;
    if (!drag.active && Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) < 7) return;
    drag.active = true; event.preventDefault(); setDraggingTaskId(drag.taskId);
    const column = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>("[data-task-status]");
    drag.status = column?.dataset.taskStatus || null; setDragOverStatus(drag.status);
  }
  async function finishPointerDrag(event: ReactPointerEvent<HTMLElement>) {
    const drag = pointerDrag.current; if (!drag) return;
    pointerDrag.current = null; if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    setDraggingTaskId(null); setDragOverStatus(null);
    if (!drag.active) return;
    suppressCardClick.current = true;
    window.setTimeout(() => { suppressCardClick.current = false; }, 150);
    const task = tasks.find((item) => item.id === drag.taskId); if (task && drag.status && task.status !== drag.status) await updateStatus(task, drag.status);
  }
  function cancelPointerDrag() { pointerDrag.current = null; setDraggingTaskId(null); setDragOverStatus(null); }
  function openTaskFromCard(task: Task) { if (suppressCardClick.current) { suppressCardClick.current = false; return; } void openTask(task); }
  async function remind(task: Task) { const response = await fetch(`/api/tasks/${task.id}/reminders`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ scheduledAt: new Date().toISOString() }) }); setError(response.ok ? `Reminder sent: ${task.title}` : (await response.json()).error); }

  function loadTaskDetail(taskId: string) { const cached = detailCache.current.get(taskId); if (cached) return cached; const request = fetch(`/api/tasks/${taskId}`).then(async (response) => { if (!response.ok) throw new Error((await response.json().catch(() => ({ error: "Unable to open task details" }))).error); const detail = await response.json(); return { ...detail, labels: detail.labels ?? [], checklistItems: detail.checklistItems ?? [], comments: detail.comments ?? [], activities: detail.activities ?? [] } as TaskDetail; }); detailCache.current.set(taskId, request); request.catch(() => detailCache.current.delete(taskId)); return request; }
  function previewTaskDetail(task: Task): TaskDetail { const creator = members.find((member) => member.user.id === task.createdByUserId)?.user; return { ...task, createdBy: creator || { id: task.createdByUserId, name: null, email: "" }, checklistItems: [], comments: [], activities: [] }; }
  async function openTask(task: Task) { setError(""); setSelected(previewTaskDetail(task)); setLoadingTaskId(task.id); try { const detail = await loadTaskDetail(task.id); setSelected((current) => current?.id === task.id ? detail : current); } catch (reason) { setError((reason as Error).message); setSelected((current) => current?.id === task.id ? null : current); } finally { setLoadingTaskId((current) => current === task.id ? null : current); } }
  async function saveTask(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!selected) return; setSaving(true); const data = new FormData(event.currentTarget); const hours = (name: string) => data.get(name) === "" ? null : Math.round(Number(data.get(name)) * 60); const response = await fetch(`/api/tasks/${selected.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: data.get("title"), description: data.get("description"), status: data.get("status"), priority: data.get("priority"), dueAt: data.get("dueAt") ? new Date(String(data.get("dueAt"))).toISOString() : null, assigneeUserId: data.get("assigneeUserId") || null, followUpWith: data.get("followUpWith") || null, recurrence: data.get("recurrence"), recurrenceInterval: Number(data.get("recurrenceInterval")), estimatedMinutes: hours("estimatedHours"), remainingMinutes: hours("remainingHours"), actualMinutes: hours("actualHours"), blockedReason: data.get("blockedReason") || null, blockerTaskId: data.get("blockerTaskId") || null, updatedProductsCount: selected.updatedProductsCount, newProductsCount: selected.newProductsCount, updatedImagesCount: selected.updatedImagesCount, newImagesCount: selected.newImagesCount }) }); setSaving(false); if (!response.ok) return setError((await response.json()).error); const updated = await response.json(); detailCache.current.delete(selected.id); const assignee = members.find((member) => member.user.id === updated.assigneeUserId)?.user || null; setTasks((items) => items.map((item) => item.id === updated.id ? { ...item, ...updated, assignee } : item)); setSelected({ ...selected, ...updated, assignee }); }
  async function setTaskLabels(labelIds: string[]) { if (!selected) return; const response = await fetch(`/api/tasks/${selected.id}/labels`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ labelIds }) }); if (!response.ok) return setError((await response.json()).error); const nextLabels = await response.json(); detailCache.current.delete(selected.id); setSelected({ ...selected, labels: nextLabels }); setTasks((items) => items.map((task) => task.id === selected.id ? { ...task, labels: nextLabels } : task)); }
  async function addComment(event: FormEvent) { event.preventDefault(); if (!selected || !comment.trim()) return; const response = await fetch(`/api/tasks/${selected.id}/comments`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ body: comment }) }); if (!response.ok) return setError((await response.json()).error); const created = await response.json(); detailCache.current.delete(selected.id); setSelected({ ...selected, comments: [...selected.comments, created], activities: [{ id: crypto.randomUUID(), type: "COMMENT_ADDED", createdAt: new Date().toISOString(), actor: created.author }, ...selected.activities] }); setComment(""); }
  async function addChecklistItem(event: FormEvent) { event.preventDefault(); if (!selected || !checklistTitle.trim()) return; const response = await fetch(`/api/tasks/${selected.id}/checklist`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: checklistTitle }) }); if (!response.ok) return setError((await response.json()).error); const item = await response.json(); detailCache.current.delete(selected.id); setSelected({ ...selected, checklistItems: [...selected.checklistItems, item] }); setChecklistTitle(""); }
  async function toggleChecklistItem(item: ChecklistItem) { if (!selected) return; const response = await fetch(`/api/tasks/${selected.id}/checklist/${item.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ completed: !item.completed }) }); if (response.ok) { detailCache.current.delete(selected.id); setSelected({ ...selected, checklistItems: selected.checklistItems.map((current) => current.id === item.id ? { ...current, completed: !item.completed } : current) }); } }
  async function createLabel(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); const response = await fetch(`/api/workspaces/${workspaceId}/labels`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: data.get("name"), color: data.get("color") }) }); if (!response.ok) return setError((await response.json()).error); const created = await response.json(); setLabels((items) => [...items, created].sort((a, b) => a.name.localeCompare(b.name))); form.reset(); setShowLabelManager(false); }
  async function saveView(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!viewName.trim()) return; const response = await fetch(`/api/workspaces/${workspaceId}/views`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: viewName, shared: shareView, filters }) }); if (!response.ok) return setError((await response.json()).error); const saved = await response.json(); setSavedViews((items) => [...items, saved]); setSelectedViewId(saved.id); setViewName(""); setShareView(false); setShowSaveView(false); }
  function applyView(id: string) { setSelectedViewId(id); const saved = savedViews.find((item) => item.id === id); setFilters(saved ? normalizeFilters(saved.filters) : { ...emptyFilters }); setOpenFilter(null); setShowMoreFilters(false); setShowMobileFilters(false); setShowSaveView(false); }
  async function deleteView() { const saved = savedViews.find((item) => item.id === selectedViewId); if (!saved || !window.confirm(`Delete the saved view “${saved.name}”?`)) return; const response = await fetch(`/api/workspaces/${workspaceId}/views/${saved.id}`, { method: "DELETE" }); if (!response.ok) return setError((await response.json()).error); setSavedViews((items) => items.filter((item) => item.id !== saved.id)); setSelectedViewId(""); }

  return <>
    <header className="page-header"><div><span className="eyebrow">PRODUCT LAUNCH</span><h1>Task board</h1><p>Move work forward, one clear task at a time.</p></div>{canCreate && <button className="primary-button small" onClick={() => setCreating(true)}>+ New task</button>}</header>
    <section className="task-insight-strip" aria-label="Task insights"><div><strong>{tasks.length}</strong><span>Total</span></div><div><strong>{visibleTasks.length}</strong><span>Visible</span></div><div className={tasks.filter((task) => needsAttention(task)).length ? "attention" : ""}><strong>{tasks.filter((task) => needsAttention(task)).length}</strong><span>Needs attention</span></div><button type="button" aria-expanded={showInsights} onClick={() => setShowInsights((value) => !value)}>{showInsights ? "Hide insights" : "View insights"}<span aria-hidden="true">{showInsights ? "⌃" : "⌄"}</span></button></section>
    {canManageWorkspace && <ManagerActionCenter actionCenter={managerActionCenter} activeRisk={riskFilter} onSelectRisk={(risk) => { setRiskFilter((current) => current === risk ? null : risk); setSelectedTaskIds(new Set()); }} />}
    {showInsights && <section className="stats task-insights-expanded"><article><small>All tasks</small><strong>{tasks.length}</strong><span>In this workspace</span></article><article><small>Visible tasks</small><strong>{visibleTasks.length}</strong><span>After filters</span></article><article><small>Needs attention</small><strong>{tasks.filter((task) => needsAttention(task)).length}</strong><span>Overdue, urgent, unassigned, or stalled</span></article></section>}
    <div className="task-controls" ref={controlsRef}>
      <section className="saved-view-bar"><div className="saved-view-select"><span>View</span><select value={selectedViewId} onChange={(event) => applyView(event.target.value)} aria-label="Saved task view"><option value="">All tasks</option>{savedViews.map((saved) => <option key={saved.id} value={saved.id}>{saved.shared ? "Shared · " : "My view · "}{saved.name}</option>)}</select></div><div className="saved-view-actions"><button type="button" className="toolbar-link" aria-expanded={showSaveView} onClick={() => { setShowSaveView((value) => !value); setOpenFilter(null); }}>Save current view</button>{selectedViewId && <button className="toolbar-link danger" onClick={deleteView}>Delete view</button>}</div>{showSaveView && <form className="saved-view-popover" onSubmit={saveView}><div><strong>Save current view</strong><small>Reuse this filter setup any time.</small></div><input value={viewName} onChange={(event) => setViewName(event.target.value)} placeholder="View name" maxLength={60} required />{canManageWorkspace && <label><input type="checkbox" checked={shareView} onChange={(event) => setShareView(event.target.checked)} /> Share with workspace</label>}<div className="popover-actions"><button type="button" className="ghost-button" onClick={() => setShowSaveView(false)}>Cancel</button><button className="primary-button small">Save view</button></div></form>}</section>
      <section className="filter-toolbar" aria-label="Task filters">
        <div className={`filter-primary-row ${showMobileFilters ? "expanded" : ""}`}>
          <div className="search-wrap"><span aria-hidden="true">⌕</span><input className="filter-search" value={filters.query} onFocus={() => { setOpenFilter(null); setShowSaveView(false); }} onChange={(event) => updateFilter("query", event.target.value)} placeholder="Search tasks..." aria-label="Search tasks" /></div>
          <button type="button" className="mobile-filter-toggle" aria-expanded={showMobileFilters} onClick={() => { setShowMobileFilters((value) => !value); setOpenFilter(null); setShowSaveView(false); }}>{showMobileFilters ? "Hide filters" : "Filters"}{filterChips.length > 0 && <strong>{filterChips.length}</strong>}<span aria-hidden="true">{showMobileFilters ? "⌃" : "⌄"}</span></button>
          <MultiFilter id="status-filter" label="Status" count={filters.statuses.length} open={openFilter === "status"} onToggle={() => toggleFilterMenu("status")}>{taskStatuses.map(([value, text]) => <label key={value}><input type="checkbox" checked={filters.statuses.includes(value)} onChange={() => updateFilter("statuses", toggleValue(filters.statuses, value))} /><span>{text}</span></label>)}</MultiFilter>
          <MultiFilter id="priority-filter" label="Priority" count={filters.priorities.length} open={openFilter === "priority"} onToggle={() => toggleFilterMenu("priority")}>{Object.entries(priority).map(([value, text]) => <label key={value}><input type="checkbox" checked={filters.priorities.includes(value)} onChange={() => updateFilter("priorities", toggleValue(filters.priorities, value))} /><span>{text}</span></label>)}</MultiFilter>
          <MultiFilter id="assignee-filter" label="Assignee" count={filters.assignees.length} open={openFilter === "assignee"} onToggle={() => toggleFilterMenu("assignee")}><label><input type="checkbox" checked={filters.assignees.includes("__unassigned__")} onChange={() => updateFilter("assignees", toggleValue(filters.assignees, "__unassigned__"))} /><span>Unassigned</span></label>{members.map((member) => <label key={member.user.id}><input type="checkbox" checked={filters.assignees.includes(member.user.id)} onChange={() => updateFilter("assignees", toggleValue(filters.assignees, member.user.id))} /><span>{personName(member)}</span></label>)}</MultiFilter>
          <button type="button" className={`quick-filter attention-filter ${filters.attention ? "active" : ""}`} aria-pressed={filters.attention} onClick={() => { updateFilter("attention", !filters.attention); setOpenFilter(null); setShowSaveView(false); }}>Needs attention</button>
          <button type="button" className={`quick-filter ${filters.mineOnly ? "active" : ""}`} aria-pressed={filters.mineOnly} onClick={() => { updateFilter("mineOnly", !filters.mineOnly); setOpenFilter(null); setShowSaveView(false); }}>My tasks</button>
          <button type="button" className={`more-filter-button ${showMoreFilters ? "active" : ""}`} aria-expanded={showMoreFilters} onClick={() => { setShowMoreFilters((value) => !value); setOpenFilter(null); setShowSaveView(false); }}>{moreFilterCount > 0 && <strong>{moreFilterCount}</strong>}More filters <span aria-hidden="true">⌄</span></button>
        </div>
        {showMoreFilters && <div className="more-filters-panel"><div className="more-filter-grid"><label><span>Created by</span><select value={filters.creator} onChange={(event) => updateFilter("creator", event.target.value)} aria-label="Filter by creator"><option value="all">All creators</option>{members.map((member) => <option key={member.user.id} value={member.user.id}>{personName(member)}</option>)}</select></label><label><span>Team group</span><select value={filters.teamGroupId} onChange={(event) => updateFilter("teamGroupId", event.target.value)} aria-label="Filter by team group"><option value="">Any team group</option><option value="__none__">No team group</option>{teamGroupOptions.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label><span>Due date</span><select value={filters.due} onChange={(event) => updateFilter("due", event.target.value)} aria-label="Filter by due date"><option value="all">Any due date</option><option value="overdue">Overdue</option><option value="today">Due today</option><option value="tomorrow">Due tomorrow</option><option value="this-week">Due this week</option><option value="next-week">Due next week</option><option value="no-date">No due date</option><option value="custom">Custom range</option></select></label><label><span>Completed</span><select value={filters.completed} onChange={(event) => updateFilter("completed", event.target.value)} aria-label="Filter by completion date"><option value="all">Any time</option><option value="today">Today</option><option value="this-week">This week</option><option value="this-month">This month</option></select></label><label><span>Recurrence</span><select value={filters.recurrence} onChange={(event) => updateFilter("recurrence", event.target.value)} aria-label="Filter by recurrence"><option value="all">Any recurrence</option><option value="recurring">Recurring</option><option value="not-recurring">Not recurring</option></select></label><label><span>Follow up with</span><select value={filters.followUpWith} onChange={(event) => updateFilter("followUpWith", event.target.value)} aria-label="Filter by follow-up person"><option value="">Any person</option><option value="__none__">No person set</option>{followUpWithOptions.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>{labels.length > 0 && <div className="more-label-filter"><span>Labels</span><MultiFilter id="label-filter" label="Choose labels" count={filters.labels.length} open={openFilter === "labels"} onToggle={() => toggleFilterMenu("labels")}>{labels.map((label) => <label key={label.id}><input type="checkbox" checked={filters.labels.includes(label.id)} onChange={() => updateFilter("labels", toggleValue(filters.labels, label.id))} /><i className="label-dot" style={{ backgroundColor: label.color }} /><span>{label.name}</span></label>)}</MultiFilter></div>}</div>{filters.due === "custom" && <div className="date-range"><label>Due from<input type="date" value={filters.dueFrom} onChange={(event) => updateFilter("dueFrom", event.target.value)} /></label><label>Due through<input type="date" value={filters.dueTo} onChange={(event) => updateFilter("dueTo", event.target.value)} /></label></div>}{canManageWorkspace && <div className="label-management"><button type="button" className="toolbar-link" onClick={() => setShowLabelManager((value) => !value)}>{showLabelManager ? "Close label manager" : "+ Create workspace label"}</button>{showLabelManager && <form onSubmit={createLabel}><input name="name" placeholder="Label name" maxLength={40} required /><input name="color" type="color" defaultValue="#176b50" aria-label="Label color" /><button className="primary-button small">Add label</button></form>}</div>}</div>}
      </section>
    </div>
    {filterChips.length > 0 && <section className="filter-chips">{filterChips.map((chip) => <span key={chip}>{chip}</span>)}<button onClick={() => { setFilters({ ...emptyFilters }); setRiskFilter(null); setSelectedViewId(""); setOpenFilter(null); setShowMoreFilters(false); setShowMobileFilters(false); }}>Clear all</button></section>}
    {selectedTaskIds.size > 0 && <BulkTaskToolbar selectedCount={selectedTaskIds.size} visibleCount={visibleTasks.length} allVisibleSelected={allVisibleSelected} members={members} labels={labels} onToggleAll={toggleAllVisibleTasks} onClear={() => setSelectedTaskIds(new Set())} onAction={bulkUpdate} />}
    <div className="view-toolbar"><nav className="view-switcher" aria-label="Task view">{(["board", "list", "calendar"] as ViewMode[]).map((mode) => <button key={mode} className={view === mode ? "active" : ""} aria-pressed={view === mode} onClick={() => setView(mode)}>{mode[0].toUpperCase() + mode.slice(1)}</button>)}</nav>{view === "board" && <label className="board-select-visible"><input type="checkbox" checked={allVisibleSelected} onChange={toggleAllVisibleTasks} aria-label="Select all visible tasks" /> Select all visible{visibleTasks.length ? ` (${visibleTasks.length})` : ""}</label>}</div>
    {error && <div className="notice">{error}</div>}
    {creating && <form action={createTask} className="create-panel"><input name="title" placeholder="What needs to be done next?" maxLength={120} required autoFocus /><select name="priority"><option value="MEDIUM">Medium</option><option value="HIGH">High</option><option value="URGENT">Urgent</option><option value="LOW">Low</option></select><select name="assigneeUserId"><option value="">Unassigned</option>{members.map((member) => <option key={member.user.id} value={member.user.id}>{personName(member)}</option>)}</select><button className="primary-button small">Add task</button><button type="button" className="ghost-button" onClick={() => setCreating(false)}>Cancel</button></form>}
    {view === "board" && <>
      {noActionNeededCount > 0 && <div className="no-action-hint"><span>{noActionNeededCount} {noActionNeededCount === 1 ? "task is" : "tasks are"} in No Action Needed and hidden from this board.</span><button type="button" onClick={() => setView("list")}>View in List</button></div>}
      <section className="board">{boardColumns.map(([status, label]) => <div className={`column drop-zone ${dragOverStatus === status ? "drag-over" : ""}`} data-task-status={status} key={status}><div className="column-title"><h2>{label}</h2><span>{grouped[status].length}</span></div><div className="cards">{grouped[status].map((task) => { const editable = canEditTask(task); return <article className={`task-card ${draggingTaskId === task.id ? "dragging" : ""}`} key={task.id} data-draggable={editable || undefined} onPointerDown={(event) => startPointerDrag(event, task)} onPointerMove={movePointerDrag} onPointerUp={finishPointerDrag} onPointerCancel={cancelPointerDrag} onClick={() => openTaskFromCard(task)}><div className="task-card-top"><input className="task-selection-checkbox" type="checkbox" checked={selectedTaskIds.has(task.id)} onChange={() => toggleTaskSelection(task.id)} onClick={(event) => event.stopPropagation()} aria-label={`Select task: ${task.title}`} /><span className={`priority ${task.priority.toLowerCase()}`}>{priority[task.priority]}</span>{task.blockedAt || task.blockerTaskId ? <span className="work-badge blocked">Blocked</span> : null}{task.remainingMinutes != null ? <span className="work-badge effort">{Math.round(task.remainingMinutes / 6) / 10}h left</span> : !task.estimatedMinutes ? <span className="work-badge unestimated">Unestimated</span> : null}{task.labels.map((item) => <span className="task-label" style={{ borderColor: item.color, color: item.color }} key={item.id}>{item.name}</span>)}</div><h3>{task.title}</h3><p>{task.description || "A focused task with no additional details."}</p><div className="task-meta"><span className="avatar mini">{task.assignee?.name?.[0] || "?"}</span><span>{task.assignee?.name || "Unassigned"}</span>{task.followUpWith && <span className="follow-up-meta">Follow up: {task.followUpWith}</span>}{dueLabel(task.dueAt, task.status === "DONE")}<button type="button" className="task-open" onClick={(event) => { event.stopPropagation(); openTask(task); }} aria-label={`Open task: ${task.title}`}>Open</button></div>{!task.assigneeUserId && assignmentControls(task, true)}{editable && <div className="card-actions" onClick={(event) => event.stopPropagation()} onKeyDown={(event) => event.stopPropagation()}><select aria-label={`Status for ${task.title}`} value={task.status} onChange={(event) => updateStatus(task, event.target.value)}>{taskStatuses.map(([value, text]) => <option value={value} key={value}>{text}</option>)}</select><button onClick={() => remind(task)} title="Send a reminder now">Remind</button></div>}</article>; })}</div></div>)}</section>
    </>}
    {view === "list" && <section className="task-list-view"><table><thead><tr><th><input type="checkbox" checked={allVisibleSelected} onChange={toggleAllVisibleTasks} aria-label="Select all visible tasks" /></th><th>Task</th><th>Status</th><th>Priority</th><th>Labels</th><th>Assignee</th><th>Due date</th></tr></thead><tbody>{visibleTasks.map((task) => <tr className={task.status === "NO_ACTION_NEEDED" ? "no-action-row" : ""} key={task.id} tabIndex={0} role="button" aria-label={`Open task: ${task.title}`} onClick={() => openTask(task)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); openTask(task); } }}><td onClick={(event) => event.stopPropagation()}><input type="checkbox" checked={selectedTaskIds.has(task.id)} onChange={() => toggleTaskSelection(task.id)} aria-label={`Select task: ${task.title}`} /></td><td><strong>{task.title}</strong><small>{task.description || "No description"}</small></td><td><select className="inline-status-select" value={task.status} disabled={!canEditTask(task)} aria-label={`Status for ${task.title}`} onClick={(event) => event.stopPropagation()} onKeyDown={(event) => event.stopPropagation()} onChange={(event) => { event.stopPropagation(); void updateStatus(task, event.target.value); }}>{taskStatuses.map(([value, text]) => <option value={value} key={value}>{text}</option>)}</select></td><td><span className={`priority ${task.priority.toLowerCase()}`}>{priority[task.priority]}</span></td><td>{task.labels.map((item) => <span className="task-label" style={{ borderColor: item.color, color: item.color }} key={item.id}>{item.name}</span>)}</td><td>{assignmentControls(task)}</td><td>{task.dueAt ? new Date(task.dueAt).toLocaleString() : "No due date"}</td></tr>)}</tbody></table>{visibleTasks.length === 0 && <div className="empty-view">No tasks match these filters.</div>}</section>}
    {view === "calendar" && <section className="calendar-view"><div className="calendar-toolbar"><button onClick={() => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() - 1, 1))}>Previous</button><h2>{calendarMonth.toLocaleDateString(undefined, { month: "long", year: "numeric" })}</h2><button onClick={() => setCalendarMonth(new Date())}>Today</button><button onClick={() => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 1))}>Next</button></div><div className="calendar-grid calendar-weekdays">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <strong key={day}>{day}</strong>)}</div><div className="calendar-grid">{calendarDays.map((day) => { const key = dateKey(day); const dayTasks = tasksByDate[key] || []; return <div className={`calendar-day ${day.getMonth() !== calendarMonth.getMonth() ? "outside" : ""}`} key={key}><span>{day.getDate()}</span>{dayTasks.map((task) => <button key={task.id} className={`calendar-task ${task.priority.toLowerCase()}`} onClick={() => openTask(task)} title={task.title}>{task.title}</button>)}</div>; })}</div>{visibleTasks.some((task) => !task.dueAt) && <div className="unscheduled"><h3>Unscheduled</h3><div>{visibleTasks.filter((task) => !task.dueAt).map((task) => <button key={task.id} onClick={() => openTask(task)}>{task.title}</button>)}</div></div>}</section>}
    {selected && <div className="drawer-backdrop" onClick={() => setSelected(null)}>
      <aside className="task-drawer" role="dialog" aria-modal="true" aria-labelledby="task-drawer-title" aria-busy={loadingTaskId === selected.id} onClick={(event) => event.stopPropagation()}>
        <button className="drawer-close" onClick={() => setSelected(null)} aria-label="Close task details">X</button>
        <span className={`priority ${selected.priority.toLowerCase()}`}>{priority[selected.priority]}</span>
        <h2 id="task-drawer-title">{selected.title}</h2>
        {!selectedEditable && <p className="read-only-note">You have read-only access to this task.</p>}
        <form onSubmit={saveTask} className="detail-form">
          <fieldset disabled={!selectedEditable}>
            <label>Title<input name="title" defaultValue={selected.title} /></label>
            <label>Description<textarea name="description" defaultValue={selected.description || ""} rows={4} /></label>
            <div className="detail-grid"><label>Status<select name="status" defaultValue={selected.status}>{taskStatuses.map(([value, text]) => <option key={value} value={value}>{text}</option>)}</select></label><label>Priority<select name="priority" defaultValue={selected.priority}>{Object.entries(priority).map(([value, text]) => <option key={value} value={value}>{text}</option>)}</select></label><label>Due date<input name="dueAt" type="datetime-local" defaultValue={selected.dueAt ? new Date(selected.dueAt).toISOString().slice(0, 16) : ""} /></label></div>
            <label>Assignee<select name="assigneeUserId" defaultValue={selected.assigneeUserId || ""}><option value="">Unassigned</option>{members.map((member) => <option key={member.user.id} value={member.user.id}>{personName(member)}</option>)}</select></label>
            <label>Follow up with<input name="followUpWith" defaultValue={selected.followUpWith || ""} maxLength={120} placeholder="Person to follow up with" /></label>
            <section className="work-planning-section" aria-labelledby="work-planning-heading">
              <div><h3 id="work-planning-heading">Work planning</h3><p>Estimate the task, keep remaining work current, and record actual effort when completed.</p></div>
              <div className="detail-grid planning-grid"><label>Estimated hours<input name="estimatedHours" type="number" min="0" max="16666" step="0.25" defaultValue={selected.estimatedMinutes == null ? "" : selected.estimatedMinutes / 60} placeholder="e.g. 4" /></label><label>Remaining hours<input name="remainingHours" type="number" min="0" max="16666" step="0.25" defaultValue={selected.remainingMinutes == null ? "" : selected.remainingMinutes / 60} placeholder="e.g. 2.5" /></label><label>Actual hours<input name="actualHours" type="number" min="0" max="16666" step="0.25" defaultValue={selected.actualMinutes == null ? "" : selected.actualMinutes / 60} placeholder="Add on completion" /></label></div>
            </section>
            <section className={`blocker-section ${selected.blockedAt || selected.blockerTaskId ? "is-blocked" : ""}`} aria-labelledby="blocker-heading">
              <div><h3 id="blocker-heading">Blockers &amp; dependencies</h3><p>Explain what is preventing progress so a manager can intervene.</p></div>
              <label>Blocked by task<select name="blockerTaskId" defaultValue={selected.blockerTaskId || ""}><option value="">No task dependency</option>{tasks.filter((task) => task.id !== selected.id && task.status !== "DONE").map((task) => <option key={task.id} value={task.id}>{task.title}</option>)}</select></label>
              <label>Blocking reason<textarea name="blockedReason" rows={2} maxLength={500} defaultValue={selected.blockedReason || ""} placeholder="Example: Waiting for approved product data" /></label>
            </section>
            <div className="detail-grid"><label>Repeat<select name="recurrence" defaultValue={selected.recurrence || "NONE"}><option value="NONE">Does not repeat</option><option value="DAILY">Daily</option><option value="WEEKLY">Weekly</option><option value="MONTHLY">Monthly</option></select></label><label>Every<input name="recurrenceInterval" type="number" min="1" max="365" defaultValue={selected.recurrenceInterval || 1} /></label></div>
            <small className="field-help">A new task is created automatically when this one is completed.</small>
            <section className="task-count-section" aria-labelledby="task-count-heading">
              <div className="task-count-heading"><h3 id="task-count-heading">Product &amp; image counts</h3><p>Select every applicable metric and enter its count.</p></div>
              <div className="task-count-options">{taskCountOptions.map(({ key, label }) => { const enabled = selected[key] !== null; return <div className={`task-count-option ${enabled ? "selected" : ""}`} key={key}><label className="task-count-toggle"><input type="checkbox" checked={enabled} onChange={(event) => setSelected((current) => current ? { ...current, [key]: event.target.checked ? 0 : null } : current)} /><span>{label}</span></label><input className="task-count-input" type="number" min="0" max="1000000000" step="1" inputMode="numeric" aria-label={`${label} value`} disabled={!enabled} value={enabled ? selected[key] ?? 0 : ""} placeholder="0" onChange={(event) => { const value = Math.max(0, Math.min(1_000_000_000, Math.trunc(Number(event.target.value) || 0))); setSelected((current) => current ? { ...current, [key]: value } : current); }} /></div>; })}</div>
            </section>
            {selectedEditable && <button className="primary-button" disabled={saving}>{saving ? "Saving..." : "Save changes"}</button>}
          </fieldset>
        </form>
        {!!selected.sourceEmails?.length && <section className="drawer-section source-email-section"><h3>Source email</h3>{selected.sourceEmails.map((email) => <article key={email.id}><strong>{email.subject}</strong><span>{email.senderAddress} → {email.connector.mailboxAddress}</span><small>{new Date(email.receivedAt).toLocaleString()}</small></article>)}</section>}
        <section className="drawer-section"><h3>Labels</h3>{labels.length ? <div className="drawer-labels">{labels.map((label) => <label key={label.id}><input type="checkbox" disabled={!selectedEditable} checked={selected.labels.some((item) => item.id === label.id)} onChange={() => setTaskLabels(toggleValue(selected.labels.map((item) => item.id), label.id))} /><i className="label-dot" style={{ backgroundColor: label.color }} /> {label.name}</label>)}</div> : <p className="empty-copy">No workspace labels yet.</p>}</section>
        <section className="drawer-section"><h3>Checklist ({selected.checklistItems.filter((item) => item.completed).length}/{selected.checklistItems.length})</h3>{selected.checklistItems.map((item) => <label className="checklist-item" key={item.id}><input type="checkbox" disabled={!selectedEditable} checked={item.completed} onChange={() => toggleChecklistItem(item)} /><span className={item.completed ? "completed" : ""}>{item.title}</span></label>)}{selectedEditable && <form onSubmit={addChecklistItem} className="comment-form"><input value={checklistTitle} onChange={(event) => setChecklistTitle(event.target.value)} placeholder="Add checklist item..." maxLength={200} /><button className="ghost-button">Add item</button></form>}</section>
        <section className="drawer-section"><h3>Comments</h3>{selected.comments.map((item) => <div className="comment" key={item.id}><strong>{item.author.name || item.author.email}</strong><p>{item.body}</p><small>{new Date(item.createdAt).toLocaleString()}</small></div>)}{selectedEditable && <form onSubmit={addComment} className="comment-form"><textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Write a comment..." rows={3} /><button className="ghost-button">Add comment</button></form>}</section>
        <section className="drawer-section"><h3>Activity</h3>{selected.activities.map((item) => <p className="activity-row" key={item.id}><strong>{item.actor.name || item.actor.email}</strong> {item.type.toLowerCase().replaceAll("_", " ")} <small>{new Date(item.createdAt).toLocaleString()}</small></p>)}</section>
      </aside>
    </div>}
    {selected && loadingTaskId === selected.id && <div className="task-detail-progress" role="status"><span aria-hidden="true" /> Loading the latest details...</div>}
  </>;
}
